function forecastChart(hist,forecast,cap,level){
 const w=900,h=380,l=58,r=42,t=34,b=55,n=hist.length+forecast.length,cut=hist.length,max=Math.ceil(Math.max(...hist,...forecast.map(x=>x.p90),cap)*1.12/50)*50;
 const X=i=>l+i*(w-l-r)/(n-1),Y=v=>h-b-v/max*(h-t-b),points=(arr,offset)=>arr.map((v,i)=>X(i+offset)+","+Y(v)).join(" "),q=k=>forecast.map(x=>x[k]);
 const band=(low,high)=>q(high).map((v,i)=>X(cut+i)+","+Y(v)).concat(q(low).map((v,i)=>X(cut+i)+","+Y(v)).reverse()).join(" ");
 const line=(arr,offset,color,width,dash="")=>'<polyline points="'+points(arr,offset)+'" fill="none" stroke="'+color+'" stroke-width="'+width+'" stroke-linejoin="round" '+(dash?'stroke-dasharray="'+dash+'"':'')+'/>';
 let s='<svg class="forecast-svg" role="img" aria-label="Histórico y distribución predictiva: percentiles 10, 20, 50, 80 y 90, capacidad disponible" viewBox="0 0 '+w+' '+h+'"><rect x="'+(X(cut)-7)+'" y="'+t+'" width="'+(w-r-X(cut)+7)+'" height="'+(h-t-b)+'" fill="#f0f7f5"/>';
 for(let i=0;i<=5;i++){const val=max*i/5;s+='<line x1="'+l+'" x2="'+(w-r)+'" y1="'+Y(val)+'" y2="'+Y(val)+'" stroke="#dce6e6"/><text x="'+(l-10)+'" y="'+(Y(val)+5)+'" text-anchor="end">'+fmt(val)+'</text>';}
 s+='<text x="'+l+'" y="18" style="font-weight:700">Expediciones / día</text><text x="'+(X(cut)+6)+'" y="18" style="font-weight:700;fill:#36776d">PREVISIÓN</text>';
 s+='<polygon points="'+band("p10","p90")+'" fill="#b4c7e4" opacity=".55"/><polygon points="'+band("p20","p80")+'" fill="#74b9a9" opacity=".48"/>';
 s+=line(hist,0,"#64788e",2.7)+line(q("p10"),cut,"#8098bc",1.5,"4 5")+line(q("p90"),cut,"#5979b1",2,"5 4")+line(q("p80"),cut,"#ae762e",2.2,"5 4")+line(q("p50"),cut,"#176d5c",3.5);
 s+='<line x1="'+l+'" x2="'+(w-r)+'" y1="'+Y(cap)+'" y2="'+Y(cap)+'" stroke="#a84741" stroke-width="2" stroke-dasharray="8 5"/><text x="'+(w-r-3)+'" y="'+Math.max(t+15,Y(cap)-7)+'" text-anchor="end" style="fill:#a84741;font-weight:700">Capacidad '+cap+'</text>';
 const marks=[0,Math.floor((forecast.length-1)/2),forecast.length-1];for(const i of marks){for(const [k,c] of [["p10","#8098bc"],["p50","#176d5c"],["p80","#ae762e"],["p90","#5979b1"]])s+='<circle cx="'+X(cut+i)+'" cy="'+Y(forecast[i][k])+'" r="'+(k==="p50"?4.5:3)+'" fill="'+c+'" stroke="white" stroke-width="1.5"><title>D+'+(i+1)+' '+k.toUpperCase()+': '+fmt(forecast[i][k])+'</title></circle>';}
 for(let i=0;i<hist.length;i+=7)s+='<text x="'+X(i)+'" y="'+(h-29)+'" text-anchor="middle">D-'+(hist.length-i)+'</text>';
 for(let i=0;i<forecast.length;i+=7)s+='<text x="'+X(cut+i)+'" y="'+(h-29)+'" text-anchor="middle">D+'+(i+1)+'</text>';
 s+='<line id="forecast-cursor" x1="'+X(cut)+'" x2="'+X(cut)+'" y1="'+t+'" y2="'+(h-b)+'" stroke="#243e50" stroke-width="1.4" stroke-dasharray="3 3"/><text x="'+l+'" y="'+(h-6)+'" style="font-size:12px">Histórico sintético</text></svg>';
 const pointsData=esc(JSON.stringify(forecast.map((x,i)=>({...x,x:X(cut+i)}))));
 return '<div class="forecast-legend"><span><i style="background:#64788e"></i>Histórico</span><span><i style="background:#176d5c"></i>P50 · central</span><span><i style="background:#ae762e"></i>P80 · planificación</span><span><i style="background:#5979b1"></i>P90 · prudente</span><span><i style="background:#b4c7e4"></i>P10–P90 · 80% central</span><span><i style="background:#74b9a9"></i>P20–P80 · 60% central</span><span><i style="background:#a84741"></i>Capacidad</span></div><div class="forecast-scroll">'+s+'</div><div class="percentile-explain"><div><strong>P10 · demanda baja</strong><span>10 de cada 100 resultados simulados quedan aproximadamente en este nivel o por debajo.</span></div><div><strong>P50 · punto central</strong><span>50 de cada 100 resultados quedan aproximadamente cubiertos.</span></div><div><strong>P80 · más cobertura</strong><span>Cubre aproximadamente 80 de cada 100 resultados; 20 podrían superarlo.</span></div><div><strong>P90 · mayor protección</strong><span>Cubre aproximadamente 90 de cada 100 resultados; exige más reserva.</span></div></div><div class="forecast-inspector" data-points="'+pointsData+'" data-cap="'+cap+'" data-level="'+level+'"><div class="inspector-head"><label for="forecast-day">Desliza para consultar cualquier día</label><strong id="forecast-day-label">D+1</strong></div><input id="forecast-day" type="range" min="1" max="'+forecast.length+'" value="1" aria-label="Día previsto"><div id="forecast-detail" class="quantile-grid"></div><div class="policy-actions"><span>¿Qué nivel quieres cubrir?</span><button type="button" data-policy="0">P50 · Equilibrado</button><button type="button" data-policy="1">P80 · Cobertura</button><button type="button" data-policy="2">P90 · Prudente</button></div><div id="forecast-capacity" class="capacity-compare"></div><p id="forecast-decision" class="forecast-decision"></p><p class="forecast-note">Cobertura diaria estimada con datos sintéticos; no garantiza el nivel de servicio real ni el cumplimiento de todo el horizonte.</p></div>';
}
let inspectedDay=1;
function bindForecast(){
 const el=document.querySelector(".forecast-inspector");if(!el)return;
 const data=JSON.parse(el.dataset.points),cap=Number(el.dataset.cap),level=el.dataset.level;
 $("forecast-day").value=Math.min(inspectedDay,data.length);const update=()=>{const idx=Number($("forecast-day").value)-1,p=data[idx];inspectedDay=idx+1;$("forecast-day-label").textContent="D+"+(idx+1);const cursor=$("forecast-cursor");cursor.setAttribute("x1",p.x);cursor.setAttribute("x2",p.x);
 $("forecast-detail").innerHTML=[["P10","Bajo",p.p10],["P50","Central",p.p50],["P80","Planificación",p.p80],["P90","Prudente",p.p90]].map(([key,label,v])=>'<div class="quantile '+(key.toLowerCase()===level?'selected':'')+'"><small>'+key+' · '+label+'</small><strong>'+fmt(v)+'</strong><small>expediciones</small></div>').join("");
 const target=Math.ceil(p[level]),extra=Math.max(0,target-cap),surplus=Math.max(0,cap-target);$("forecast-capacity").innerHTML='<div><small>Capacidad disponible</small><strong>'+cap+'</strong></div><div><small>Capacidad objetivo · '+level.toUpperCase()+'</small><strong>'+target+'</strong></div><div class="'+(extra?"capacity-gap":"capacity-ok")+'"><small>'+(extra?"Refuerzo necesario":"Margen de capacidad")+'</small><strong>'+(extra?"+"+extra:surplus)+' exped.</strong></div>';$("forecast-decision").textContent=(extra?"Reserva "+extra+" expediciones adicionales para cubrir "+level.toUpperCase()+".":"La capacidad actual cubre "+level.toUpperCase()+"; tienes "+surplus+" expediciones de margen frente a este objetivo.")+" Con la capacidad actual, el "+pct(p.risk)+" de resultados simulados la supera.";};
 $("forecast-day").addEventListener("input",update);document.querySelectorAll("[data-policy]").forEach(b=>{b.setAttribute("aria-pressed",String(["p50","p80","p90"][Number(b.dataset.policy)]===level));b.onclick=()=>{const e=document.querySelector('[data-input="4"]');e.value=b.dataset.policy;onInput(e);};});update();
}
