function sync(){const u=new URL(location.href);u.searchParams.set("perfil",profile);u.searchParams.set("reto",active);history.replaceState(null,"",u);}
function updateProfile(){const p=profiles[profile];$("role-picker").value=profile;$("role-desc").textContent=p[1];$("role-count").textContent=p[2].length+" herramientas recomendadas";renderMenu();}
function renderMenu(){const p=profiles[profile];let sequence=0;const mobile=$("mobile-tools");mobile.replaceChildren();$("menu").replaceChildren();for(const g of ["Control de operaciones","Planificación y optimización","Fiabilidad y servicio","Rentabilidad y costes","Automatización y control"]){const list=cases.filter(c=>c[1]===g&&p[2].includes(c[0]));if(!list.length)continue;const el=document.createElement("p");el.className="group";el.textContent=g;$("menu").append(el);for(const c of list){const b=document.createElement("button");b.className="navcase";b.dataset.case=c[0];b.setAttribute("aria-current",String(c[0]===active));b.innerHTML='<span class="num">'+String(++sequence).padStart(2,"0")+'</span><span>'+esc(c[2])+'</span>';b.onclick=()=>select(c[0],true);$("menu").append(b);const o=document.createElement("option");o.value=c[0];o.textContent=String(sequence).padStart(2,"0")+" · "+c[2];mobile.append(o);}}}

/* Decision layer: comparable hypotheses evaluated using the same synthetic data and model. */
const decisionSpecs={
torre:{owner:"Responsable de tráfico",rule:"Si quedan pedidos sin asignar, resolverlos primero. Ajustar el umbral al número de alertas que el equipo puede revisar.",check:"Confirmar estado real y capacidad del equipo; cambiar un umbral no reduce el riesgo.",opts:[["Vigilancia intensiva",1,25,"Si bajamos el umbral, detectaremos más expediciones para revisión, pero aumentará la carga del equipo."],["Vigilancia selectiva",1,45,"Si centramos la revisión en alertas intermedias y altas, reduciremos el volumen de avisos."],["Solo alertas críticas",1,75,"Si elevamos el umbral, se revisarán menos expediciones y algunas señales quedarán sin atender."]]},
rutas:{owner:"Dirección de operaciones",rule:"Priorizar más entregas factibles y, en caso de empate, menor coste variable entre estas estrategias.",check:"Validar ventanas, tráfico por carretera, disponibilidad y prioridad contractual antes de despachar.",opts:[["Minimizar distancia",4,0,"Si priorizamos cercanía, podemos reducir desplazamientos, pero dejar algunos pedidos difíciles sin asignar."],["Priorizar clientes críticos",4,1,"Si adelantamos pedidos prioritarios, podemos proteger compromisos importantes a costa de kilómetros adicionales."],["Equilibrar carga",4,2,"Si distribuimos el trabajo, podemos aprovechar mejor la flota, aunque algunas rutas sean más largas."]],rank:"routes"},
demanda:{owner:"Dirección de operaciones / planificación",rule:"Elegir la política según coste de capacidad ociosa, coste de incumplimiento y objetivo de cobertura; P80 es un punto de partida para discutir, no un óptimo.",check:"Validar previsiones con históricos reales y confirmar coste de reserva, SLA y disponibilidad.",opts:[["Planificar con P50",4,0,"Si dimensionamos con la mediana, limitamos la reserva, pero aceptamos mayor exposición a picos."],["Planificar con P80",4,1,"Si reservamos hasta P80, protegemos más días frente a excesos de demanda con una reserva intermedia."],["Planificar con P90",4,2,"Si reservamos hasta P90, reducimos exposición a picos a cambio de más capacidad comprometida."]],rank:"forecast"},
flota:{owner:"Responsable de flota",rule:"Cubrir los picos con el menor número de vehículos posible entre las alternativas; si ninguna cubre todas las franjas, negociar refuerzo.",check:"Comprobar turnos, descansos, disponibilidad, costes y compatibilidad de vehículos.",opts:[["Mantener la flota",1,"same","Si conservamos la dotación, evitamos nuevas contrataciones pero asumimos los picos actuales."],["Añadir dos vehículos",1,"+2","Si incorporamos dos vehículos, aumentará la capacidad; necesitamos confirmar su coste."],["Añadir cuatro vehículos",1,"+4","Si ampliamos más, podemos cubrir picos mayores, con mayor coste y posible ociosidad."]],rank:"fleet"},
retrasos:{owner:"Tráfico y atención al cliente",rule:"Revisar primero las expediciones de mayor riesgo. Reducir la congestión es una hipótesis de intervención, no un efecto causal demostrado.",check:"Confirmar el ETA con el conductor y la viabilidad de una ruta alternativa antes de avisar al cliente.",opts:[["Mantener condiciones",3,"same","Si no intervenimos sobre la congestión, conservamos la exposición estimada actual."],["Mitigar congestión",3,"-10","Si una ruta alternativa reduce la congestión adicional en 10 puntos, el modelo estima un nuevo riesgo y ETA."],["Proteger una ventana crítica",3,0,"Si logramos eliminar la congestión adicional supuesta, recalculamos el riesgo residual; no desaparecen otras causas."]]},
incidencias:{owner:"Dirección de operaciones",rule:"Minimizar el coste de contingencia supuesto entre las opciones, incluyendo entregas no servidas; proteger pedidos críticos.",check:"Confirmar disponibilidad externa, precio, compatibilidad y penalizaciones reales antes de contratar.",opts:[["Absorber con flota propia",2,0,"Si no contratamos refuerzo, ahorramos gasto externo pero quedan más entregas sin cubrir."],["Activar refuerzo parcial",2,40,"Si contratamos hasta 40 entregas externas, recuperamos parte del servicio con un coste adicional."],["Activar refuerzo amplio",2,100,"Si contratamos hasta 100 entregas externas, recuperamos más servicio si hay capacidad disponible."]],rank:"incident"},
muelles:{owner:"Responsable de almacén",rule:"Buscar la menor cola al cierre; contrastar la mejora con coste de personal e infraestructura.",check:"Validar disponibilidad de muelles, citas y duración real de descarga.",opts:[["Mantener recepción",1,"same","Si mantenemos los muelles actuales, conservamos el coste de capacidad y la cola estimada."],["Abrir un muelle adicional",1,"+1","Si abrimos un muelle adicional, aumenta la capacidad horaria y puede reducirse la cola."],["Abrir dos muelles adicionales",1,"+2","Si añadimos dos muelles, podemos reducir más la acumulación, con más recursos comprometidos."]],rank:"dock"},
rentabilidad:{owner:"Dirección financiera / comercial",rule:"Investigar primero contratos con baja contribución. Contrastar ahorros potenciales con coste de implantación y efectos en el servicio.",check:"Validar costes completos y no tratar una reducción supuesta de coste como ahorro realizado.",opts:[["Mantener coste actual",2,"same","Si no modificamos el coste kilométrico, se mantiene la contribución calculada."],["Reducir coste 10 cént./km",2,"-10","Si reducimos el coste por kilómetro en diez céntimos, mejora la contribución bajo volumen y precios constantes."],["Reducir coste 20 cént./km",2,"-20","Si alcanzamos una reducción mayor, estimamos el potencial adicional; puede requerir cambios operativos o inversión."]]},
retornos:{owner:"Responsable comercial / tráfico",rule:"Aceptar únicamente cargas que pasen las restricciones reales y aporten contribución incremental.",check:"Las oportunidades pueden competir por el mismo vehículo; no sumar potencial como beneficio asegurado.",opts:[["Desvío conservador",1,15,"Si limitamos el desvío, reducimos kilómetros extra y el número de candidatos."],["Desvío moderado",1,35,"Si ampliamos el radio, aparecen más oportunidades potenciales."],["Desvío amplio",1,65,"Si aceptamos desvíos mayores, pueden aumentar las oportunidades, pero también tiempo y coste."]]},
tarifas:{owner:"Dirección comercial / financiera",rule:"Cotizar solo con margen objetivo y capacidad confirmada. No confundir un precio hipotético con aceptación del cliente.",check:"Validar elasticidad, SLA, coste completo y oferta de transportista.",opts:[["Mantener oferta",1,"same","Si mantenemos el precio, conservamos el margen estimado bajo los costes actuales."],["Revisar tarifa +100 €",1,"+100","Si el cliente acepta cien euros adicionales, aumenta la contribución por servicio; desconocemos su aceptación."],["Revisar tarifa +200 €",1,"+200","Si acepta una tarifa mayor, aumentaría el margen, pero podría reducirse la probabilidad de cerrar la oferta."]]},
transportistas:{owner:"Compras / dirección de operaciones",rule:"Elegir ponderaciones según el SLA contractual y revisar el proveedor resultante; no hay un ranking universal.",check:"Validar capacidad, reclamaciones, seguro, desempeño y contrato antes de asignar volumen.",opts:[["Priorizar coste",1,25,"Si damos más peso al coste, puede liderar un proveedor económico con menor puntualidad."],["Equilibrar criterios",1,60,"Si combinamos servicio y coste, buscamos una solución intermedia."],["Priorizar puntualidad",1,90,"Si damos prioridad al servicio, puede liderar un proveedor más fiable y caro."]]},
almacen:{owner:"Dirección de almacén",rule:"Si una zona supera el 100%, preparar desvío o capacidad adicional; por encima del 85%, revisar reservas y citas.",check:"Confirmar capacidad física, pedidos y entradas comprometidas; el crecimiento es un supuesto.",opts:[["Entradas previstas",1,"same","Si se mantienen las entradas previstas, observamos el nivel actual de presión."],["Escalonar entradas (−10 puntos)",1,"-10","Si podemos repartir entradas a otros días, baja la presión del periodo mostrado."],["Escalonar entradas (−20 puntos)",1,"-20","Si desplazamos más entradas, podría evitarse saturación, trasladando carga a otras fechas."]],rank:"warehouse"},
mantenimiento:{owner:"Responsable de mantenimiento",rule:"Inspeccionar vehículos de mayor índice según disponibilidad de taller y criticidad; el índice no es probabilidad de avería.",check:"Confirmar señales de diagnóstico e inspección profesional antes de retirar un vehículo.",opts:[["Revisión preventiva amplia",1,40,"Si bajamos el umbral, más vehículos pasan a revisión y aumentan las horas de taller."],["Revisión focalizada",1,65,"Si mantenemos un umbral intermedio, concentramos inspecciones en las señales más relevantes."],["Solo prioridad crítica",1,85,"Si elevamos el umbral, reducimos revisiones, pero podemos posponer señales relevantes."]]},
simulacion:{owner:"Dirección de operaciones / riesgos",rule:"Comparar riesgo de falta de capacidad, nivel de servicio y P90 de pendientes; definir el presupuesto y riesgo tolerable antes de reservar.",check:"Los costes de capacidad no están en este modelo; validar distribuciones, correlaciones y disponibilidad.",opts:[["Capacidad actual",2,"same","Si no aumentamos la capacidad nominal, conservamos el riesgo estimado."],["Reserva de 30 expediciones",2,"+30","Si añadimos treinta expediciones de capacidad nominal, estimamos el riesgo residual con las mismas jornadas simuladas."],["Reserva de 60 expediciones",2,"+60","Si añadimos sesenta, podemos reducir más el riesgo, pero aumenta el coste de reserva."]]},
anomalias:{owner:"Control financiero",rule:"Priorizar revisión de desviaciones relevantes según impacto económico y capacidad de auditoría.",check:"Una alerta no confirma error; cotejar documentación antes de reclamar o imputar costes.",opts:[["Auditoría amplia",1,10,"Si reducimos tolerancia, se revisan más servicios y aumenta la carga de auditoría."],["Auditoría focalizada",1,20,"Si elegimos un umbral intermedio, concentramos la revisión en desviaciones relevantes."],["Solo grandes desviaciones",1,40,"Si elevamos tolerancia, se reducen revisiones y pueden quedar desviaciones menores sin investigar."]]},
documentos:{owner:"Administración / finanzas",rule:"Definir tolerancia contractual y exigir revisión humana ante falta de prueba de entrega o datos críticos.",check:"No emitir facturas ni liberar pagos automáticamente desde esta demo.",opts:[["Control estricto",1,0,"Si exigimos coincidencia exacta en tarifas, aumentan las revisiones, pero reducimos tolerancia a discrepancias."],["Tolerancia moderada",1,5,"Si aceptamos pequeñas diferencias según política, más registros pueden pasar reglas automáticas."],["Tolerancia amplia",1,10,"Si ampliamos tolerancia, reducimos revisiones manuales, pero aumenta la exposición a diferencias no revisadas."]]}
};
function metricPairs(html){return [...html.matchAll(/<div class="metric"><small>(.*?)<\/small><strong>(.*?)<\/strong><\/div>/g)].map(m=>[m[1].replace(/&amp;/g,"&"),m[2].replace(/&amp;/g,"&")]);}
function alternativeValues(id,values,option){const i=option[1],raw=option[2],d=defs[id][i],n=values.slice();let v=raw==="same"?n[i]:typeof raw==="string"?n[i]+Number(raw):raw;n[i]=d[0]==="select"?clamp(v,0,d[2].length-1):clamp(v,d[2],d[3]);return n;}
function decisionEvaluate(id,values,result){
 const spec=decisionSpecs[id],savedMap=mapState,baseMetrics=metricPairs(result[0]);
 const number=(x,i)=>{const v=x.metrics[i]?.[1]||"";return Number(v.split("/")[0].replace(/\s/g,"").replace(/\.(?=\d{3}(?:\D|$))/g,"").replace(",",".").replace(/[^\d.-]/g,""))||0;};
 const options=spec.opts.map((o,i)=>{const vals=alternativeValues(id,values,o),same=vals.every((v,j)=>v===values[j]);const r=same?result:renderers[id](vals);return {i,title:o[0],hypothesis:o[3],values:vals,metrics:metricPairs(r[0]),same,change:defs[id][o[1]][1]+": "+(defs[id][o[1]][0]==="select"?defs[id][o[1]][2][vals[o[1]]]:vals[o[1]])};});
 mapState=savedMap;
 let recommended=null,reason=spec.rule;
 if(spec.rank==="routes"){recommended=options.slice().sort((a,b)=>number(b,0)-number(a,0)||number(a,3)-number(b,3))[0];reason="Entre las tres estrategias evaluadas, "+recommended.title.toLowerCase()+" planifica "+recommended.metrics[0][1]+" entregas con un coste variable estimado de "+recommended.metrics[3][1]+". Se prioriza cobertura y después coste.";}
 if(spec.rank==="fleet"){recommended=options.slice().sort((a,b)=>number(a,2)-number(b,2)||a.values[1]-b.values[1])[0];reason="Entre las opciones probadas, "+recommended.title.toLowerCase()+" deja "+recommended.metrics[2][1]+" franjas saturadas con "+recommended.values[1]+" vehículos. El coste de ampliar flota todavía debe validarse.";}
 if(spec.rank==="incident"){const cost=o=>number(o,3)+95*number(o,2);recommended=options.slice().sort((a,b)=>cost(a)-cost(b))[0];reason="Con los costes supuestos (45 € por entrega externa, 95 € por entrega no servida), "+recommended.title.toLowerCase()+" presenta el menor coste de contingencia comparado: "+euro(cost(recommended))+".";}
 if(spec.rank==="dock"){recommended=options.slice().sort((a,b)=>number(a,2)-number(b,2)||number(a,1)-number(b,1)||a.values[1]-b.values[1])[0];reason="La alternativa "+recommended.title.toLowerCase()+" deja "+recommended.metrics[2][1]+" pendientes al cierre y una cola máxima estimada de "+recommended.metrics[1][1]+". Falta valorar el coste de capacidad adicional.";}
 if(spec.rank==="warehouse"){recommended=options.slice().sort((a,b)=>number(a,2)-number(b,2)||number(a,1)-number(b,1)||b.values[1]-a.values[1])[0];reason="Para reducir saturación en este periodo, "+recommended.title.toLowerCase()+" deja "+recommended.metrics[2][1]+" zonas por encima de capacidad. Confirmar que desplazar entradas es viable.";}
 if(spec.rank==="forecast"){const chosen=options[values[4]??1]||options[1];reason="Con tu política actual ("+chosen.title+"), se estima un refuerzo máximo de "+chosen.metrics[2][1]+" y "+chosen.metrics[1][1]+" días con refuerzo. Compara P50, P80 y P90 antes de comprometer capacidad.";}
 return {id,spec,baseMetrics,options,recommended,reason};
}

const decisionConditions={
torre:["Si hay capacidad de revisión suficiente y pedidos sensibles.","Si el equipo necesita concentrarse en las incidencias relevantes.","Si los recursos son limitados, mantener seguimiento de las alertas descartadas."],
rutas:["Si todas las ventanas y pedidos críticos quedan cubiertos, y el coste es la prioridad.","Si existen compromisos contractuales o clientes cuyo incumplimiento tiene mayor impacto.","Si hay desequilibrio entre vehículos y la jornada permite redistribuir pedidos."],
demanda:["Si el refuerzo es costoso y se acepta una mayor exposición a picos.","Si se busca mayor cobertura con una reserva intermedia y hay recursos flexibles.","Si el incumplimiento es especialmente costoso o existen compromisos de servicio exigentes."],
flota:["Si no hay franjas saturadas o se pueden desplazar pedidos sin incumplir ventanas.","Si el refuerzo cubre los picos y su coste es asumible.","Si persisten franjas saturadas y existe capacidad adicional disponible."],
retrasos:["Si la exposición es aceptable y no hay una alternativa viable, reforzar el seguimiento.","Si existe una alternativa que realmente permite reducir la congestión prevista.","Si se puede evitar la congestión adicional y la ventana contractual es crítica."],
incidencias:["Si las entregas pendientes pueden aplazarse sin afectar compromisos críticos.","Si hay proveedores disponibles y el coste evitado supera el coste del refuerzo.","Si el volumen afectado exige más apoyo y la capacidad externa está confirmada."],
muelles:["Si la cola es asumible y los compromisos de descarga se mantienen.","Si hay acumulación y un muelle adicional está disponible a coste razonable.","Si un muelle adicional no basta y el volumen justifica más personal y espacio."],
rentabilidad:["Si el margen satisface el objetivo y el nivel de servicio es adecuado.","Si se identifican ahorros operativos viables sin degradar el servicio.","Si el ahorro adicional compensa el coste de implantación y no compromete el contrato."],
retornos:["Si la ventana de entrega es ajustada o el vehículo tiene poca flexibilidad.","Si existe tiempo suficiente y la contribución incremental compensa el desvío.","Si la carga compensa el recorrido extra y se cumplen todas las ventanas y restricciones."],
tarifas:["Si el margen cumple el objetivo y la capacidad está confirmada.","Si el mercado permite renegociar y el nuevo precio mejora la contribución.","Si el servicio tiene valor diferencial y se valida la disposición a pagar."],
transportistas:["Si los proveedores cumplen el mínimo contractual de puntualidad y se prioriza el coste.","Si coste y servicio son relevantes y no hay un requisito dominante.","Si el SLA es crítico y el sobrecoste es aceptable."],
almacen:["Si la capacidad física puede absorber las entradas previstas.","Si proveedores y clientes permiten redistribuir parte de las entradas.","Si persiste saturación y el calendario permite trasladar más volumen sin crear otro cuello de botella."],
mantenimiento:["Si hay taller disponible y conviene investigar señales tempranas.","Si hay que equilibrar las horas de taller con las necesidades de flota.","Si el taller tiene capacidad limitada; no posponer inspecciones obligatorias."],
simulacion:["Si el riesgo actual queda dentro del nivel tolerado por la empresa.","Si la reserva reduce suficientemente el riesgo a un coste asumible.","Si la exposición residual sigue siendo elevada y el SLA justifica una reserva mayor."],
anomalias:["Si el equipo puede revisar más servicios y se quiere detectar desviaciones tempranas.","Si la capacidad de auditoría es limitada y se prioriza impacto económico.","Si hay que concentrarse en grandes desviaciones sin perder el seguimiento de las menores."],
documentos:["Si el contrato exige coincidencia exacta o existe riesgo financiero relevante.","Si la política contractual admite pequeñas diferencias y hay revisión de excepciones.","Solo si el contrato lo permite y existen controles adicionales; nunca omitir datos críticos."]
};
function decisionReading(id,m){
 const v=i=>m[i]?.[1]||"—", n=i=>Number(v(i).split("/")[0].replace(/\s/g,"").replace(/\.(?=\d{3}(?:\D|$))/g,"").replace(",",".").replace(/[^\d.-]/g,""))||0;
 const lines={
 torre:()=>["De "+v(0)+" pedidos, "+v(1)+" están planificados y "+v(3)+" siguen pendientes.","El umbral actual genera "+v(2)+" alertas de revisión.",n(3)>0?"La prioridad es asignar los pedidos pendientes y después revisar alertas.":"El foco pasa a las ventanas comprometidas y el seguimiento de alertas."],
 rutas:()=>["El plan actual cubre "+v(0)+" entregas y deja "+v(2)+" sin asignar.","Recorre "+v(1)+" con un coste variable estimado de "+v(3)+".",n(2)>0?"Hay entregas que no caben en el plan: revisar recursos, ventanas o prioridades antes de despachar.":"La cobertura es completa en el modelo; el siguiente objetivo es reducir coste sin perder servicio."],
 demanda:()=>["La demanda central prevista es de "+v(0)+" expediciones diarias.","Con la política actual, hay "+v(1)+" días que requieren refuerzo; el máximo es "+v(2)+".","El riesgo medio diario de superar la capacidad actual es "+v(3)+". La reserva debe equilibrar ese riesgo con su coste."],
 flota:()=>["Disponemos de "+v(0)+" pedidos de capacidad por franja frente a un pico de "+v(1)+".","Se estiman "+v(2)+" franjas saturadas.",n(2)>0?"Revisar refuerzos o desplazar pedidos flexibles.":"La capacidad cubre las franjas analizadas; comprobar si existe ociosidad."],
 retrasos:()=>["Se analizan "+v(0)+" expediciones y "+v(1)+" superan el umbral de alerta.","El riesgo medio estimado es "+v(2)+".","Revisar primero las expediciones de mayor riesgo; el modelo no demuestra causalidad."],
 incidencias:()=>["La incidencia afecta a "+v(0)+" pedidos y el refuerzo recupera "+v(1)+".","Quedan "+v(2)+" sin cubrir; el coste externo estimado es "+v(3)+".",n(2)>0?"Hay que negociar capacidad adicional o reordenar prioridades.":"El refuerzo cubre el volumen afectado en este cálculo."],
 muelles:()=>["La capacidad estimada es de "+v(0)+" descargas por hora.","La cola máxima alcanza "+v(1)+" y quedan "+v(2)+" pendientes al cierre.",n(2)>0?"La recepción no absorbe toda la carga; revisar citas y capacidad.":"No quedan pendientes al cierre, aunque pueden existir picos intermedios."],
 rentabilidad:()=>["Los ingresos analizados ascienden a "+v(0)+".","La contribución calculada es "+v(1)+", con un margen de "+v(2)+".","Identificar los clientes de menor contribución antes de renegociar tarifas o reducir costes."],
 retornos:()=>["Se identifican "+v(0)+" cargas compatibles con el filtro actual.","Su contribución potencial conjunta es "+v(1)+".","Son oportunidades candidatas: comprobar compatibilidad simultánea antes de reservar vehículos."],
 tarifas:()=>["La oferta actual es de "+v(0)+"; el precio mínimo propio para el margen objetivo es "+v(1)+".","La mejor contribución estimada es "+v(2)+".",n(0)<n(1)?"La oferta no alcanza el objetivo propio: revisar tarifa o modalidad.":"La oferta cubre el objetivo propio en el modelo; validar disponibilidad y aceptación."],
 transportistas:()=>["Con las ponderaciones actuales lidera "+v(0)+".","Presenta una puntualidad de "+v(1)+" y un coste de "+v(2)+" por entrega.","La elección depende del SLA y de la importancia relativa del coste."],
 almacen:()=>["La ocupación máxima prevista alcanza "+v(0)+".","Hay "+v(1)+" zonas por encima del 85% y "+v(2)+" por encima de capacidad.",n(2)>0?"Hay riesgo de saturación física: preparar desvío de entradas o espacio adicional.":"Vigilar las zonas cercanas al límite antes de aceptar más volumen."],
 mantenimiento:()=>["Se analizan "+v(0)+" vehículos y "+v(1)+" requieren revisión prioritaria.","El mayor índice de revisión es "+v(2)+".","Organizar inspecciones según criticidad y disponibilidad; el índice no es una probabilidad de avería."],
 simulacion:()=>["En "+v(0)+" jornadas simuladas, la falta de capacidad aparece en "+v(1)+".","El nivel medio de servicio es "+v(2)+" y el P90 de pedidos pendientes es "+v(3)+".","Evaluar reservas adicionales según la tolerancia al riesgo y su coste."],
 anomalias:()=>["De "+v(0)+" servicios analizados, "+v(1)+" generan alertas.","El exceso total sobre la referencia es "+v(2)+".","Priorizar revisiones documentales: la desviación no demuestra fraude ni ahorro recuperable."],
 documentos:()=>["De "+v(0)+" documentos, "+v(1)+" requieren revisión humana.","Los otros "+v(2)+" pasan las reglas actuales.","Resolver discrepancias y datos críticos antes de emitir facturas o autorizar pagos."]
 };
 return lines[id]();
}
function decisionHTML(d){
 const {id,spec,baseMetrics,options,recommended,reason}=d;
 return '<section id="decision-center" class="decision-center" aria-label="Recomendación ejecutiva"><header class="decision-heading"><div><span class="decision-kicker">INTELIGENCIA DE DECISIÓN</span><h3>Conclusiones y decisiones a tomar</h3><p>De los resultados a las acciones: interpreta la situación, compara alternativas y decide según las condiciones de tu operación.</p></div><span class="decision-symbol" aria-hidden="true">↗</span></header><section class="decision-reading"><h4>¿Qué nos dicen estos datos?</h4>'+decisionReading(id,baseMetrics).map((line,i)=>'<div class="reading-line"><span>'+String(i+1).padStart(2,"0")+'</span><p>'+esc(line)+'</p></div>').join("")+'</section><div class="decision-summary"><span class="decision-label">'+(recommended?"ALTERNATIVA PRIORITARIA · CRITERIO DEL MODELO":"CRITERIO DE DECISIÓN · CONDICIONADO")+'</span><h4>'+esc(recommended?recommended.title:"Evaluar antes de comprometer recursos")+'</h4><p>'+esc(reason)+'</p><small><strong>Responsable:</strong> '+esc(spec.owner)+'</small></div><h4 class="decision-actions-title">Decisiones posibles según tu situación</h4><div class="decision-options">'+options.map((o,i)=>'<article class="decision-option '+(recommended?.i===i?"decision-priority":"")+'"><div class="decision-option-top"><span>HIPÓTESIS '+String(i+1).padStart(2,"0")+'</span>'+(o.same?'<small>Situación actual</small>':"")+'</div><h4>'+esc(o.title)+'</h4><div class="decision-condition"><strong>Cuándo aplicarla</strong><p>'+esc(decisionConditions[id][i])+'</p></div><div class="decision-consequence"><strong>Qué podría suceder</strong><p>'+esc(o.hypothesis)+'</p></div><div class="decision-metrics">'+o.metrics.filter((m,j)=>!(active==="simulacion"&&j===0)&&!(active==="retrasos"&&j===3)).map(m=>'<div><small>'+esc(m[0])+'</small><strong>'+esc(m[1])+'</strong></div>').join("")+'</div><div class="decision-assumption">'+esc(o.change)+'</div><button type="button" data-decision-option="'+i+'">Probar esta decisión →</button></article>').join("")+'</div><div class="decision-guard"><strong>Antes de ejecutar</strong><p>'+esc(spec.check)+'</p><small>Consecuencias calculadas sobre datos sintéticos, no resultados garantizados. Las opciones no cubren todos los costes ni restricciones reales.</small></div></section>';
}
let currentDecision=null;
function bindDecisions(){document.querySelectorAll("[data-decision-option]").forEach(b=>b.onclick=()=>{const o=currentDecision?.options[Number(b.dataset.decisionOption)];if(!o)return;const id=active;if(!confirm("¿Aplicar esta hipótesis a los parámetros de la demo?"))return;const fields=[...document.querySelectorAll("[data-input]")];fields.forEach((e,i)=>{e.value=o.values[i];const out=$("val"+i);if(out)out.textContent=e.value;});snapshots[id]=currentMetrics();state[id]=getv();if(explicit.has(id))execute();else render();$("tool-parameters").scrollIntoView({block:"center",behavior:"smooth"});});}
function render(values=getv()){if(mapInstance){mapInstance.remove();mapInstance=null;}mapState=null;const result=renderers[active](values),[m,v,action,method]=result;executed=values.slice();currentDecision=decisionEvaluate(active,values,result);lastResult={action:currentDecision.reason,method};$("results").innerHTML=m+'<div class="viz">'+v+'</div>'+decisionHTML(currentDecision)+'<details class="details"><summary>Datos y límites del ejemplo</summary><p>'+esc(method)+'</p></details>';bindMap();bindForecast();bindDecisions();if(!$("view-panel").hidden)renderView();$("results").setAttribute("aria-busy","false");setStatus("Resultados actualizados · datos sintéticos","done");clearAssistant();updateAgentContext();if(agentApplied?.id===active){const prev=snapshots[active]||[],now=currentMetrics(),reply=$("assistant-answer")?.querySelector(".assistant-reply");if(reply)reply.innerHTML="<h4>Cambio aplicado · resultados actualizados</h4>"+table(["Indicador","Antes","Ahora"],now.map(m=>[m.name,prev.find(x=>x.name===m.name)?.value||"—",m.value]))+"<p>"+esc(lastResult.action)+"</p>";agentApplied=null;}}
async function execute(){const token=++runToken,id=active,g=guides[id],values=getv().slice(),b=$("run-model");if(!b)return;b.disabled=true;clearAssistant();$("results").setAttribute("aria-busy","true");for(const [i,s] of ["Preparar datos y parámetros",g[4],g[5]].entries()){setStatus((i+1)+"/3 · "+s+"…","loading");await wait(500);if(token!==runToken||id!==active)return;}render(values);b.disabled=false;if(dirty())setStatus("Cambios pendientes · ejecutar de nuevo.","pending");}
function instant(id,i){return !explicit.has(id)||(id==="demanda"&&[2,4].includes(i))||(id==="retrasos"&&[0,1,2,4].includes(i))||(id==="documentos"&&i===0);}
