function setAgentOpen(open){agentOpen=open;document.body.classList.toggle("agent-open",open);$("agent-dock").hidden=!open;$("agent-launch").hidden=open;$("agent-launch").setAttribute("aria-expanded",String(open));if(open)$("assistant-input").focus({preventScroll:true});else $("agent-launch").focus({preventScroll:true});}
