function updateHistory(){if(!$("agent-history"))return;$("agent-history").innerHTML=chatLog.map(x=>'<div><small>'+esc(x.tool)+'</small><p>'+esc(x.text)+'</p></div>').join("");$("history-count").textContent=chatLog.length?"Historial ("+chatLog.length+")":"Historial";}
function updateAgentContext(){if(!$("agent-context"))return;const c=cases.find(c=>c[0]===active);$("agent-context").textContent=c[2];$("agent-profile").textContent=profiles[profile][0].split(" · ")[0];$("agent-examples").innerHTML=defs[active].map((d,i)=>'<button type="button" data-agent-field="'+i+'">'+esc(d[1])+'</button>').join("");document.querySelectorAll("[data-agent-field]").forEach(b=>b.onclick=()=>{const d=defs[active][Number(b.dataset.agentField)];$("assistant-input").value=d[0]==="select"?"Seleccionar "+d[2][(getv()[Number(b.dataset.agentField)]+1)%d[2].length]:"Cambiar "+d[1]+" a ";$("assistant-input").focus();});}
